  function apply(lang){localStorage.setItem('litbuy-language',lang);document.documentElement.lang=lang;const map=d[lang]||{};textNodes().forEach(n=>{if(!originals.has(n))originals.set(n,n.nodeValue);const s=originals.get(n),m=s.match(/^(\s*)(.*?)(\s*)$/s);if(m)n.nodeValue=m[1]+(map[m[2]]||m[2])+m[3]});document.querySelectorAll('[data-language-select]').forEach(s=>s.value=lang);document.querySelectorAll('input[placeholder]').forEach(i=>{if(!i.dataset.originalPlaceholder)i.dataset.originalPlaceholder=i.placeholder;i.placeholder=lang==='en'?i.dataset.originalPlaceholder:(map.Search||'Search')+' FindSpreadsheet'});document.querySelectorAll('.faq details,.list details').forEach((el,i)=>{const sum=el.querySelector('summary'),p=el.querySelector('p');if(!sum)return;if(!sum.dataset.english)sum.dataset.english=sum.textContent;if(p&&!p.dataset.english)p.dataset.english=p.textContent;const row=faq[lang]?.[i];sum.textContent=row?row[0]:sum.dataset.english;if(p)p.textContent=row?row[1]:p.dataset.english});const box=document.querySelector('.article-box.article-scroll');if(box){const h=box.querySelector('h3'),ps=[...box.querySelectorAll('p')],x=seo[lang];if(h&&!h.dataset.english)h.dataset.english=h.textContent;ps.forEach(p=>{if(!p.dataset.english)p.dataset.english=p.textContent});if(x){h.textContent=x[0];ps.forEach((p,i)=>p.textContent=x[i+1]||p.dataset.english)}else{h.textContent=h.dataset.english;ps.forEach(p=>p.textContent=p.dataset.english)}}const article=document.querySelector('article.article');if(article){if(!article.dataset.englishHtml)article.dataset.englishHtml=article.innerHTML;const g=guide[lang],hero=document.querySelector('.hero h1'),meta=document.querySelector('.meta');if(!hero.dataset.english)hero.dataset.english=hero.textContent;if(meta&&!meta.dataset.english)meta.dataset.english=meta.textContent;if(!g){article.innerHTML=article.dataset.englishHtml;hero.textContent=hero.dataset.english;if(meta)meta.textContent=meta.dataset.english}else{hero.textContent=g.title;if(meta)meta.textContent=g.meta;article.innerHTML=g.heads.map((h,i)=>'<h2>'+h+'</h2><p>'+g.paras[i]+'</p><p>'+g.paras[i]+'</p>').join('')+'<div class="source"><strong>'+d[lang]['LITBUY FAQ · FACT CHECKED']+'</strong> '+g.paras[0]+'</div>'}}const c=pageCopy[lang];if(!c)return;const path=location.pathname;if(path==='/'||path==='/index.html'){set(document.querySelector('.mast h1'),c.mast);set(document.querySelector('.mast p'),c.homeIntro);set(document.querySelector('.search-inner b'),c.searchLead);set(document.querySelector('.category-section .section-head h2'),c.catTitle);set(document.querySelector('.category-section .section-head p'),c.catIntro);set(document.querySelector('.feature .section-head h2'),c.featureTitle);set(document.querySelector('.feature .section-head p'),c.featureIntro);set(document.querySelector('#products .section-head h2'),c.productTitle);set(document.querySelector('#products .section-head p'),c.productIntro);set(document.querySelector('.faq-section .section-head p'),c.faqIntro);set(document.querySelector('.footerin span:last-child'),c.footer);document.querySelectorAll('.category b').forEach((el,i)=>set(el,c.names[i]));document.querySelectorAll('.category span:not(.category-icon)').forEach(el=>set(el,c.cardDesc))}else if(path==='/categories/'||path==='/categories/index.html'){set(document.querySelector('.hero>.eyebrow'),c.categoryHero);set(document.querySelector('.hero h1'),c.categoryTitle);set(document.querySelector('.hero p'),c.catIntro);document.querySelectorAll('.card b').forEach((el,i)=>set(el,c.names[i]));document.querySelectorAll('.card span:last-child').forEach(el=>set(el,c.cardDesc))}else if(path==='/product-detail/'||path==='/product-detail/index.html'){set(document.querySelector('.hero>.eyebrow'),d[lang]['PRODUCT DETAILS / MAIN SITE']);set(document.querySelector('.hero h1'),c.productTitle);set(document.querySelector('.hero p'),c.productHero)}else if(path==='/blog/'||path==='/blog/index.html'){set(document.querySelector('.hero h1'),c.blogHero);document.querySelectorAll('.post h2').forEach((el,i)=>set(el,c.blogTitles[i]));document.querySelectorAll('.post p').forEach(el=>set(el,c.cardDesc))}}
  function mount(){if(!document.querySelector('[data-language-select]')){const holder=document.createElement('label');holder.className='language-picker';holder.innerHTML='<span>Language</span><select data-language-select aria-label="Language"></select>';const select=holder.querySelector('select');langs.forEach(([id,label])=>select.insertAdjacentHTML('beforeend',`<option value="${id}">${label}</option>`));select.addEventListener('change',()=>apply(select.value));const nav=document.querySelector('header .nav');if(nav)nav.after(holder);else document.querySelector('header')?.append(holder);const style=document.createElement('style');style.textContent='.language-picker{display:inline-flex;align-items:center;gap:7px;background:#101113;color:#fff;padding:7px 9px;font:bold .72rem Arial;white-space:nowrap}.language-picker select{appearance:none;border:0;background:transparent;color:#fff;font:inherit;cursor:pointer;outline:0}.language-picker option{background:#101113;color:#fff}';document.head.append(style)}apply(localStorage.getItem('litbuy-language')||'en')}
  function preserveFullGuide(lang){const a=document.querySelector('article.article'),g=guide[lang];if(!a||!g)return;const pairs=g.heads.map((h,i)=>'<h2>'+h+'</h2><p>'+g.paras[i]+'</p><p>'+g.paras[i]+' '+g.paras[(i+1)%g.paras.length]+'</p>').join('');a.innerHTML='<p>'+g.paras[0]+' '+g.paras[1]+'</p><p>'+g.paras[2]+' '+g.paras[3]+'</p><div class="note"><b>'+d[lang]['LITBUY GUIDE']+':</b> '+g.paras[0]+' '+g.paras[4]+'</div>'+pairs+'<ul class="checklist"><li><b>01</b>'+g.heads[0]+'</li><li><b>02</b>'+g.heads[1]+'</li><li><b>03</b>'+g.heads[2]+'</li><li><b>04</b>'+g.heads[3]+'</li><li><b>05</b>'+g.heads[4]+'</li></ul><div class="source"><strong>'+d[lang]['LITBUY FAQ · FACT CHECKED']+':</strong> '+g.paras[5]+' '+g.paras[6]+'</div>'}
  window.addEventListener('change',e=>{if(!e.target.matches?.('[data-language-select]'))return;if(e.target.value==='en'){setTimeout(()=>location.reload(),0);return}const lang=e.target.value,restore=()=>preserveFullGuide(lang);restore();requestAnimationFrame(restore);setTimeout(restore,80)});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{mount();preserveFullGuide(localStorage.getItem('litbuy-language')||'en')});else{mount();preserveFullGuide(localStorage.getItem('litbuy-language')||'en')}
